const SHELL_FILES=['./','./index.html','./manifest.webmanifest','./icons/icon-192.png','./icons/icon-180.png'];
const base=()=>self.registration.scope;
const relOf=u=>{const s=base();const h=u.split('#')[0].split('?')[0];return h.startsWith(s)?decodeURI(h.slice(s.length)):null;};
self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(SHELL).then(c=>c.addAll(SHELL_FILES).catch(()=>{})));});
// eski tam önbellekten (descent-vNN) içeriği aynı kalan dosyalar yeni varlık önbelleğine taşınır (SHA-1 karşılaştırması, en çok 25 sn)
async function migrate(oldName){const t0=Date.now();const o=await caches.open(oldName);const a=await caches.open(ASSET);const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
  for(const req of await o.keys()){if(Date.now()-t0>25000)break;const rel=relOf(req.url);if(!rel||!REV[rel])continue;const key=base()+rel+'?r='+REV[rel];if(await a.match(key))continue;
    try{const res=await o.match(req);if(!res||res.status!==200)continue;const buf=await res.clone().arrayBuffer();const h=hex(await crypto.subtle.digest('SHA-1',buf)).slice(0,12);if(h===REV[rel])await a.put(key,res);}catch(_){}}}
self.addEventListener('activate',e=>{e.waitUntil((async()=>{const ks=await caches.keys();
  for(const k of ks)if(/^descent-v\d+$/.test(k)){try{await migrate(k);}catch(_){}}
  await Promise.all(ks.filter(k=>k!==SHELL&&k!==ASSET).map(k=>caches.delete(k)));
  // değişmiş/kaldırılmış dosyaların eski kopyaları silinir
  try{const a=await caches.open(ASSET);for(const r of await a.keys()){const u=new URL(r.url);const rel=relOf(r.url);if(!rel||REV[rel]!==u.searchParams.get('r'))await a.delete(r);}}catch(_){}
  await self.clients.claim();})());});
self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;const u=new URL(req.url);if(u.origin!==location.origin)return;
  const rel=relOf(req.url);
  // sayfa ve küçük ayar dosyaları (library.json, version.json…): önce ağ (güncelleme hemen gelsin), ağ yoksa önbellek
  const rv=rel&&REV[rel];
  if(req.mode==='navigate'||rel===''||rel==='index.html'||(!rv&&/\.(json|js|webmanifest)$/.test(rel||''))){e.respondWith(fetch(req,{cache:'no-store'}).then(res=>{if(res.ok){const cp=res.clone();caches.open(SHELL).then(c=>c.put(req,cp)).catch(()=>{});}return res;})
      .catch(()=>caches.match(req,{ignoreSearch:true}).then(r=>r||caches.match('./index.html'))));return;}
  if(!rv)return;// listede olmayan: doğrudan ağ
  if(req.headers.has('range'))return;// video parça istekleri önbelleğe girmez
  const key=base()+rel+'?r='+rv;
  e.respondWith(caches.open(ASSET).then(c=>c.match(key).then(hit=>hit||fetch(req).then(res=>{if(res.status===200){const cp=res.clone();c.put(key,cp).catch(()=>{});}return res;}))).catch(()=>fetch(req)));});
